/**
 * 精简楷体字体模块
 * 从系统楷体(simkai.ttf)抽取页面所需863个字符
 *
 * 加载策略：
 *   1. 尝试 wx.loadFontFace（base64 内嵌）
 *   2. 失败时静默降级，不影响页面渲染
 *   3. 所有 CSS 字体栈均已配置系统字体 fallback
 */
var kaitiBase64 = ''

/**
 * 加载自定义楷体字体（可选增强，失败不影响页面渲染）
 * @param {function} [callback] - callback(success: boolean)
 */
function loadKaitiFont(callback) {
  if (typeof wx !== "object" || !wx.loadFontFace) {
    console.log("[kaiti] wx.loadFontFace 不可用，使用系统字体")
    if (callback) callback(false)
    return
  }
  try {
    wx.loadFontFace({
      family: "KaitiSubset",
      source: "url(data:font/truetype;base64," + kaitiBase64 + ")",
      global: true,
      success: function() {
        console.log("[kaiti] 楷体加载成功")
        if (callback) callback(true)
      },
      fail: function(err) {
        var msg = err && err.errMsg ? err.errMsg : String(err)
        console.warn("[kaiti] 楷体加载失败（将使用系统字体降级）: " + msg)
        if (callback) callback(false)
      }
    })
  } catch(e) {
    var emsg = e && e.message ? e.message : String(e)
    console.warn("[kaiti] loadFontFace 异常: " + emsg)
    if (callback) callback(false)
  }
}

module.exports = { loadKaitiFont: loadKaitiFont }